import sys, json, pathlib, importlib
before=set(sys.modules)
ORDER=['errors', 'primitives', 'states']
for name in ORDER:
    exec('from logistics_domain import '+name)
import logistics_domain as package
out={'order':ORDER,'cwd':str(pathlib.Path.cwd()),'isolated':sys.flags.isolated,'exports':{},'pending':{},'unknown':None}
for name in ('errors','primitives','states'):
    actual=getattr(package,name)
    assert actual is importlib.import_module('logistics_domain.'+name)
    assert name in package.__all__
    out['exports'][name]=str(pathlib.Path(actual.__file__).resolve())
for name in ('entities','ids','units','ports'):
    try: getattr(package,name)
    except NotImplementedError as e:
        assert name in str(e) and 'not implemented yet' in str(e)
        out['pending'][name]=type(e).__name__
    else: raise AssertionError('undelivered API unexpectedly succeeded: '+name)
try:getattr(package,'n05_unknown_name')
except AttributeError:out['unknown']='AttributeError'
else:raise AssertionError('unknown API unexpectedly succeeded')
roots={name.split('.',1)[0] for name in set(sys.modules)-before}
third=sorted(roots-set(sys.stdlib_module_names)-{'logistics_domain'})
assert not third, third
out['third_party_roots']=third
assert out['isolated']==1
print(json.dumps(out))

